package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkFragment;import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import com.hmdp.ai.domain.knowledge.parsing.ParsedDocument;import org.springframework.stereotype.Component;import java.util.*;
@Component public class ParagraphChunkingStrategy implements ChunkingStrategy {public String code(){return "PARAGRAPH";}public List<ChunkFragment> chunk(ParsedDocument d,ChunkingPolicy p){List<ChunkFragment>out=new ArrayList<>();StringBuilder group=new StringBuilder();for(String paragraph:d.getPlainText().split("\\R\\s*\\R")){if(group.length()>0&&group.length()+paragraph.length()>p.getMaxChars()){out.addAll(ChunkingSupport.windows(group.toString(),p,null,d.getTitle(),null,null));group.setLength(0);}if(group.length()>0)group.append("\n\n");group.append(paragraph);}out.addAll(ChunkingSupport.windows(group.toString(),p,null,d.getTitle(),null,null));return out;}}
